WITH cleaned AS (SELECT *, CONCAT_WS('/', level, email) level_email_key FROM employees WHERE hire_date > DATE '2023-02-19'), latest AS (SELECT * FROM cleaned QUALIFY ROW_NUMBER() OVER (PARTITION BY manager_id ORDER BY salary DESC, id) = 1), joined AS (SELECT s.*, p.job_title AS employee_job_title, p.level AS employee_level, p.hire_date AS employee_hire_date FROM latest s LEFT JOIN employees p ON s.manager_id = p.id WHERE p.is_remote), ranked AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY level ORDER BY salary) AS row_num FROM joined) ranked WHERE row_num = 1), latest_employees AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY dept_id ORDER BY hire_date DESC) AS latest_rank FROM ranked) x WHERE latest_rank = 1), wide AS (SELECT * FROM (SELECT employee_job_title, employee_level, salary FROM latest_employees) src PIVOT (AVG(salary) AS total FOR employee_level IN ('L4', 'L1'))) SELECT employee_job_title, L4, L1 FROM wide;
